const COUNTRY_KEYS = Object.keys(INTERNATIONAL_SUPPORT_DIRECTORY);

/** Resolve explicit country names/codes before city names to avoid guessing. */
export function resolveSupportCountry(location = "") {
  const normalized = String(location).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
  if (!normalized) return null;
  for (const country of COUNTRY_KEYS) {
    const { countryCode, aliases = [] } = INTERNATIONAL_SUPPORT_DIRECTORY[country];
    const candidates = [country.toLowerCase(), countryCode.toLowerCase(), ...aliases];
    if (candidates.some((alias) => new RegExp(`(?:^|[^a-z0-9])${alias.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?:$|[^a-z0-9])`).test(normalized))) return country;
  }
  // A bare major city is accepted as a convenience. For a multi-part place
  // such as "London, Ontario", require the user to include the country.
  if (!normalized.includes(",")) {
    for (const country of COUNTRY_KEYS) {
      if (INTERNATIONAL_SUPPORT_DIRECTORY[country].cityAliases?.includes(normalized)) return country;
    }
  }
  return null;
}

export function getCountrySupportResources(country, category) {
  const entry = INTERNATIONAL_SUPPORT_DIRECTORY[country];
  if (!entry) return [];
  const key = category === "providers" || category === "assistance" ? "programs" :
    category === "government_assistance" ? "grants" : category === "emergency" ? "hotlines" : category;
  return [...(entry.categories[key] || [])];
}
